    /// Handle to an acceleration structure. See the "Ray tracing" section header for its lifetime rules.
    [StructLayout(LayoutKind.Sequential)]
    public unsafe struct SturdyAccelerationStructure
    {
        public ulong id;
    }

    /// Handle to a GPU buffer. See the "RHI resources" section header for its lifetime rules.
    [StructLayout(LayoutKind.Sequential)]
    public unsafe struct SturdyBuffer
    {
        public ulong id;
    }

    /// Procedural (AABB) geometry within an acceleration structure build.
    [StructLayout(LayoutKind.Sequential)]
    public unsafe struct SturdyAccelerationStructureAabbsDesc
    {
        public SturdyBuffer buffer;
        public ulong offset;
        public ulong stride;
    }

    /// Describes one acceleration structure build (or update, if `src` is nonzero). `geometries` must match what was passed to `sturdy_rhi_acceleration_structure_build_sizes` when `dst` was sized.
    [StructLayout(LayoutKind.Sequential)]
    public unsafe struct SturdyAccelerationStructureBuildDesc
    {
        public SturdyAccelerationStructureType type;
        public uint flags;
        public SturdyAccelerationStructure dst;
        public SturdyAccelerationStructure src;
        public SturdyBuffer scratch_buffer;
        public ulong scratch_offset;
        public uint geometry_count;
        public SturdyAccelerationStructureGeometryDesc* geometries;
        public uint range_count;
        public SturdyAccelerationStructureBuildRangeInfo* ranges;
    }

    /// How many primitives (and at what offsets) each geometry in a build contributes. Index-aligned with the build's `geometries` array.
    [StructLayout(LayoutKind.Sequential)]
    public unsafe struct SturdyAccelerationStructureBuildRangeInfo
    {
        public uint primitive_count;
        public uint primitive_offset;
        public uint first_vertex;
        public uint transform_offset;
    }

    /// Buffer sizes needed to build an acceleration structure, returned by `sturdy_rhi_acceleration_structure_build_sizes`.
    [StructLayout(LayoutKind.Sequential)]
    public unsafe struct SturdyAccelerationStructureBuildSizes
    {
        public ulong acceleration_structure_size;
        public ulong build_scratch_size;
        public ulong update_scratch_size;
    }

    [StructLayout(LayoutKind.Sequential)]
    public unsafe struct SturdyAccelerationStructureCopyDesc
    {
        public SturdyAccelerationStructure src;
        public SturdyAccelerationStructure dst;
        public SturdyAccelerationStructureCopyMode mode;
    }

    /// Describes an acceleration structure to create. `size` must come from `sturdy_rhi_acceleration_structure_build_sizes`.
    [StructLayout(LayoutKind.Sequential)]
    public unsafe struct SturdyAccelerationStructureDesc
    {
        public uint struct_size;
        public SturdyAccelerationStructureType type;
        public ulong size;
        public byte* label;
    }

    /// Handle to an opacity micromap. Not supported on D3D12 — see the "Ray tracing" section header.
    [StructLayout(LayoutKind.Sequential)]
    public unsafe struct SturdyOpacityMicromap
    {
        public ulong id;
    }

    /// Triangle geometry within an acceleration structure build. `opacity_micromap` is a zero handle unless `Feature`-gated opacity micromaps are used (Vulkan only).
    [StructLayout(LayoutKind.Sequential)]
    public unsafe struct SturdyAccelerationStructureTrianglesDesc
    {
        public SturdyBuffer vertex_buffer;
        public ulong vertex_offset;
        public SturdyVertexFormat vertex_format;
        public ulong vertex_stride;
        public uint max_vertex;
        public SturdyBuffer index_buffer;
        public ulong index_offset;
        public SturdyIndexFormat index_format;
        public SturdyBuffer transform_buffer;
        public ulong transform_offset;
        public SturdyOpacityMicromap opacity_micromap;
        public SturdyBuffer opacity_micromap_index_buffer;
        public ulong opacity_micromap_index_offset;
        public SturdyIndexFormat opacity_micromap_index_format;
    }

    /// Top-level instance geometry within an acceleration structure build.
    [StructLayout(LayoutKind.Sequential)]
    public unsafe struct SturdyAccelerationStructureInstancesDesc
    {
        public SturdyBuffer buffer;
        public ulong offset;
        public byte array_of_pointers;
    }

    /// One geometry entry in an acceleration structure build. `type` selects which of `triangles`/`aabbs`/`instances` is meaningful; the other two are ignored. Mirrors `RHI::AccelerationStructureGeometryDesc`, which carries all three as plain members rather than a tagged union.
    [StructLayout(LayoutKind.Sequential)]
    public unsafe struct SturdyAccelerationStructureGeometryDesc
    {
        public SturdyAccelerationStructureGeometryType type;
        public uint flags;
        public SturdyAccelerationStructureTrianglesDesc triangles;
        public SturdyAccelerationStructureAabbsDesc aabbs;
        public SturdyAccelerationStructureInstancesDesc instances;
    }

    /// One row of a top-level acceleration structure's instance buffer. Fixed 64-byte layout matching `VkAccelerationStructureInstanceKHR`/`D3D12_RAYTRACING_INSTANCE_DESC` exactly (and `RHI::AccelerationStructureInstance`) — write an array of these directly into a mapped/staged buffer bound as `SturdyAccelerationStructureInstancesDesc::buffer`.
    [StructLayout(LayoutKind.Sequential)]
    public unsafe struct SturdyAccelerationStructureInstance
    {
        public fixed float transform[12];
        public uint custom_index_and_mask;
        public uint shader_binding_table_offset_and_flags;
        public ulong acceleration_structure_device_address;
    }

